            "id": "55",
            "title": "Mass Times",
            "alias": "mass-times",
            "categoryId": "24",
            "categoryTitle": "Homepage Articles",
            "introtext": "\t<h1>Sunday Liturgies</h1>\n<p>Saturday: 5:30pm<br />Sunday: 8am, 10:30am, &amp; 12:30pm</p>\n<h1>Weekday Masses</h1>\n<p>Tuesday, Thursday, &amp; Friday: 9am<br />Wednesday: 5:30pm</p>\n<h1>Weekday Communion Services</h1>\n<p>Monday &amp; Wednesday: 9am</p>\n<h1>Reconciliation</h1>\n<p>Saturday: 4:30-5pm<br />Also by appointment, please call Fr. Joe</p>\n<p><a class=\"button\" href=\"livestream\">Watch Mass Live</a></p>",
            "fulltext": "",
            "state": "1",
            "access": "1"
          }
        ]
      },
      {
        "particleId": "contentarray-9079",
        "particleTitle": "Parish Mission",
        "particleType": "contentarray",
        "filterPath": "utility > grid-4722 > block-1540 > contentarray-9079.attributes.article.filter",
