        "articles": [
          {
            "id": "56",
            "title": "Parish Mission",
            "alias": "mission-statement",
            "categoryId": "24",
            "categoryTitle": "Homepage Articles",
            "introtext": "\t<div class=\"mission-wrapper\">\n<div class=\"mission-title\">\n<h1>Parish Mission</h1>\n</div>\n<div class=\"mission-content\">\n<p><strong>The mission of Saint Christopher Parish is to participate in Christ's mission of evangelization by witnessing and sharing in the mission of Jesus who calls us to love God with our whole hearts and to love neighbors, even as God loves us. We attempt to carry out our mission through our worship, service, faith formation, community life and stewardship.</strong></p>\n<p class=\"nomargin\"><strong>Saint Christopher's participation in this mission is expressed:</strong></p>\n<ul>\n<li>through our communal celebration of the sacraments and formation by the Word of God;</li>\n<li>through many ministries, especially through the authenticity of our daily living;</li>\n<li>through seeking the challenge of new ministries whenever and wherever greater needs emerge;</li>\n<li>through inviting all to share their gifts in reaching out and working lovingly among people;</li>\n<li>through witnessing the truth that God is with us as we serve at the parish, deanery and Archdiocesan level.</li>\n</ul>\n</div>\n</div>",
            "fulltext": "",
            "state": "1",
            "access": "1"
          }
        ]
      },
